import re

def next_field(line, start):
    # Regular expression to match a field, considering escaped quotes
    match = re.match(r'"([^"\\]*(\\.[^"\\]*)*)"|([^,"]+)', line[start:])
    if match:
        field = match.group(0)
        # Replace escaped double quotes with a single double quote
        field = field.replace(r'\"', '"')
        # Remove surrounding quotes if present
        if field.startswith('"') and field.endswith('"'):
            field = field[1:-1]
        # Calculate the end of the current field
        end = start + match.end()
        if match.group(1) or match.group(2):
            # If the field was quoted or not empty, find the next comma
            comma_index = line.find(',', end)
            if comma_index == -1:
                next_start = -1
            else:
                next_start = comma_index + 1
        else:
            # If the field was empty, set next_start to the end
            next_start = end
        return field, next_start
    else:
        return None, -1
